const ts = require('typescript');
const path = require('path');
const fs = require('fs');

const root = process.cwd();
const configPath = path.join(root, 'tsconfig.json');
const configFile = ts.readConfigFile(configPath, ts.sys.readFile);
if (configFile.error) {
  console.error('tsconfig read error', ts.flattenDiagnosticMessageText(configFile.error.messageText, '\n'));
  process.exit(1);
}
const parsed = ts.parseJsonConfigFileContent(configFile.config, ts.sys, root);
if (parsed.errors.length) {
  console.log('parse errors:');
  for (const d of parsed.errors) {
    console.log(ts.flattenDiagnosticMessageText(d.messageText, '\n'));
  }
}

const changed = [
  'src/api/api-types.ts',
  'src/assets/svg/BookmarkIcon.tsx',
  'src/assets/svg/VideoIcon.tsx',
  'src/assets/svg/map-pin.tsx',
  'src/assets/svg/row-waiting.tsx',
  'src/assets/svg/truck-icon-green.tsx',
  'src/components/app-page-header/app-page-header.styles.ts',
  'src/components/app-page-header/app-page-header.tsx',
  'src/components/delivery-address-sheet/delivery-address-sheet.tsx',
  'src/components/doctor-avatar/doctor-avatar.props.ts',
  'src/components/doctor-avatar/doctor-avatar.tsx',
  'src/i18n/locale/Indonesia.ts',
  'src/i18n/locale/Melayu.ts',
  'src/i18n/locale/en.ts',
  'src/i18n/locale/ph.ts',
  'src/i18n/locale/th.ts',
  'src/i18n/locale/vn.ts',
  'src/i18n/locale/zh.ts',
  'src/i18n/locale/zh_tw.ts',
  'src/navigation/types.ts',
  'src/screens/appointments-screen/appointments-screen.styles.ts',
  'src/screens/appointments-screen/appointments-screen.tsx',
  'src/screens/doctor-detail-screen/doctor-booking-flow.ts',
  'src/screens/doctor-detail-screen/doctor-detail-screen.props.ts',
  'src/screens/doctor-detail-screen/doctor-detail-screen.styles.ts',
  'src/screens/doctor-detail-screen/doctor-detail-screen.tsx',
  'src/screens/my-appointment-screen/my-appointment-screen.tsx',
  'src/screens/my-appointment-screen/my-appointment-screen.utils.ts',
  'src/screens/profile/profile-screen/profile-screen.styles.ts',
  'src/screens/profile/profile-screen/profile-screen.tsx',
  'src/utils/selected-address.ts',
].map(p => path.join(root, p));

const program = ts.createProgram({
  rootNames: parsed.fileNames,
  options: parsed.options,
});

const changedAbs = new Set(changed.map(p => path.resolve(p)));
const sourceFiles = program.getSourceFiles();
const covered = [];
const missing = [];
for (const f of changed) {
  const sf = program.getSourceFile(f) || program.getSourceFile(path.resolve(f));
  if (sf) covered.push(f);
  else missing.push(f);
}

function printDiag(kind, d) {
  const file = d.file;
  const pos = file && d.start != null ? file.getLineAndCharacterOfPosition(d.start) : null;
  const loc = file && pos ? `${path.relative(root, file.fileName)}:${pos.line + 1}:${pos.character + 1}` : '(no file)';
  const code = `TS${d.code}`;
  const msg = ts.flattenDiagnosticMessageText(d.messageText, '\n');
  console.log(`[${kind}] ${code} ${loc} ${msg}`);
}

console.log('=== COVERAGE ===');
console.log('program files', sourceFiles.filter(sf => !sf.isDeclarationFile).length);
console.log('changed covered', covered.length);
console.log('changed missing', missing.length);
missing.forEach(m => console.log('MISSING', path.relative(root, m)));

console.log('=== SEMANTIC/SYNTACTIC for changed files ===');
let changedDiagCount = 0;
for (const sf of sourceFiles) {
  const abs = path.resolve(sf.fileName);
  if (!changedAbs.has(abs)) continue;
  const diags = [
    ...program.getSyntacticDiagnostics(sf),
    ...program.getSemanticDiagnostics(sf),
  ];
  const suggestions = program.getSuggestionDiagnostics(sf);
  for (const d of diags) {
    changedDiagCount++;
    printDiag('diag', d);
  }
  for (const d of suggestions) {
    changedDiagCount++;
    printDiag('suggestion', d);
  }
}
console.log('changed-file diagnostic count', changedDiagCount);

console.log('=== GLOBAL semantic (intersect changed) ===');
const globalDiags = ts.getPreEmitDiagnostics(program);
let globalChanged = 0;
for (const d of globalDiags) {
  if (!d.file) continue;
  const abs = path.resolve(d.file.fileName);
  if (changedAbs.has(abs)) {
    globalChanged++;
    printDiag('global', d);
  }
}
console.log('global changed-file diagnostics', globalChanged);
EOF

