const ts = require('typescript');
const path = require('path');

const root = process.cwd();
const configPath = path.join(root, 'tsconfig.json');
const configFile = ts.readConfigFile(configPath, ts.sys.readFile);
const parsed = ts.parseJsonConfigFileContent(configFile.config, ts.sys, root);

const testFiles = [
  '__tests__/app-page-header.test.tsx',
  '__tests__/appointments-i18n.test.ts',
  '__tests__/appointments-screen.test.tsx',
  '__tests__/doctor-avatar.test.tsx',
  '__tests__/doctor-booking-flow.test.ts',
  '__tests__/my-appointment-ticket-guard.test.ts',
  '__tests__/profile-screen.test.tsx',
  '__tests__/row-waiting.test.tsx',
  '__tests__/selected-address.test.ts',
].map(p => path.join(root, p));

const options = {
  ...parsed.options,
  noEmit: true,
  skipLibCheck: true,
  types: ['jest', 'node'],
};
const program = ts.createProgram({
  rootNames: [...parsed.fileNames, ...testFiles],
  options,
});

function printDiag(d) {
  const file = d.file;
  const pos = file && d.start != null ? file.getLineAndCharacterOfPosition(d.start) : null;
  const loc = file && pos ? `${path.relative(root, file.fileName)}:${pos.line + 1}` : '(no file)';
  console.log(`TS${d.code} ${loc} ${ts.flattenDiagnosticMessageText(d.messageText, '\n').split('\n')[0]}`);
}

const testAbs = new Set(testFiles.map(p => path.resolve(p)));
let count = 0;
for (const sf of program.getSourceFiles()) {
  if (!testAbs.has(path.resolve(sf.fileName))) continue;
  const diags = [
    ...program.getSyntacticDiagnostics(sf),
    ...program.getSemanticDiagnostics(sf),
    ...program.getSuggestionDiagnostics(sf),
  ];
  for (const d of diags) {
    count++;
    printDiag(d);
  }
}
console.log('test diagnostic count', count);
